.shared-card{position:relative;display:inline-block;flex:none;box-sizing:border-box;width:var(--size-length-70_0,68px);height:auto;aspect-ratio:5/7;min-width:0;min-height:0;padding:0;border:0;border-radius:var(--size-radius-9_0,8px);background:var(--color-material-card-face,#fffbed);color:var(--color-material-card-ink,#264e43);box-shadow:0 3px 0 var(--color-material-card-side,#aebcae);overflow:hidden;vertical-align:middle;}
.shared-card>.piece-art{display:block;width:100%;height:100%;aspect-ratio:5/7;}.shared-face{position:relative;box-sizing:border-box;display:grid;place-items:center;width:70px;height:98px;border:2px solid var(--color-material-card-rim,#e5e6d4);border-radius:9px;background:var(--color-material-card-face,#fffbed);color:inherit;font:800 34px/1 system-ui}
.shared-card.shared-red{color:var(--color-material-card-red,#b94f40);}.shared-card-corner{position:absolute;top:5px;left:5px;display:grid;gap:1px;text-align:center;font:800 15px/1 system-ui}.shared-card-corner small{font-size:12px}.shared-card-corner.bottom{inset:auto 5px 5px auto;transform:rotate(180deg)}
.shared-back-face{background:var(--color-material-card-back-face,#31594c);color:var(--color-material-card-back-pattern,#e8d9af);}.shared-back-face img{width:100%;height:100%;object-fit:contain;}
