.battleship-scene .battle-fields{display:block;position:relative;overflow:hidden;container-type:size;}.battleship-scene .battle-panel{display:flex;flex-direction:column;justify-content:center;align-items:center;gap:var(--size-space-4_0,4px);position:absolute;inset:0;transition:transform var(--ui-duration-page,300ms) var(--ui-easing-page,ease);will-change:transform;}.battleship-scene .battle-panel.is-active{position:absolute;display:flex;}.battleship-scene .battle-panel .battle-grid{width:min(100cqw,calc(100cqh - var(--size-length-60_0,60px)));height:auto;flex:none;margin-inline:auto;}.battleship-scene .battle-panel>.player-indicators{flex:none;min-height:var(--size-length-25_0,24px);max-width:100%;justify-content:center;align-items:center;}.battleship-scene .battle-panel .player-indicator{font-size:clamp(var(--size-type-10_0,10px),2vmin,var(--size-type-14_0,14px));}.battleship-scene .battle-panel .player-indicator svg{width:var(--size-length-22_0,20px);height:var(--size-length-16_0,16px);}.reduced-motion .battleship-scene .battle-panel{transition:none;}@media(prefers-reduced-motion:reduce){.battleship-scene .battle-panel{transition:none;}}
.battleship-scene .battle-panel .player-indicator.fleet-indicator .fleet-ship-icon{width:auto;height:var(--size-length-18_0,16px);}
.battleship-scene .fleet-indicator.is-complete{background:#d8edcf;border-color:#67945f;color:#2e623b;}
.battleship-scene .fleet-indicator.is-selected{outline:var(--size-border-2_0,2px) solid #d29a45;outline-offset:1px;}
.battleship-scene [data-drag-piece]{touch-action:none;cursor:grab;}
.battleship-scene .battle-grid{position:relative;}
.battleship-scene .battle-cell.ship>button:hover{background:transparent;}
.battleship-scene .battle-ship-selection{position:absolute;left:calc(var(--ship-x)*10%);top:calc(var(--ship-y)*10%);width:calc(var(--ship-w)*10%);height:calc(var(--ship-h)*10%);box-sizing:border-box;border:var(--size-border-3_0,2px) solid #efcb67;border-radius:var(--size-radius-4_0,4px);box-shadow:0 0 0 2px #274e52;pointer-events:none;z-index:2;}
.battleship-scene .battle-grid [data-drop-piece].playroom-drop-hover{outline-offset:-3px!important;}
.battleship-scene .layout-field,.battleship-scene .game-field-content{overflow-x:clip;}

@media(orientation:landscape){.battleship-scene .battle-panel{flex-direction:row;gap:var(--size-space-4_0,4px);}.battleship-scene .battle-panel>.player-indicators{flex-direction:column;width:var(--size-length-48_0,48px);max-width:var(--size-length-48_0,48px);align-items:stretch;}.battleship-scene .battle-panel .battle-grid{width:min(calc(100cqw - var(--size-length-52_0,52px)),100cqh);height:auto;margin:0;}.battleship-scene .battle-panel .fleet-indicator{padding:var(--size-space-2_0,2px);font-size:var(--size-type-10_0,10px);}.battleship-scene .battle-panel .fleet-ship-icon{max-width:var(--size-length-30_0,28px);}}

